return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Adto sa Plugin Search','Activate %s' => 'I-aktibo ang %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>Ang %1$s</strong> nanginahanglan og <strong>%2$s</strong> nga ma-install ug ma-aktibo. <a href="%4$s">%3$s</a>','Enter your code here' => 'Ibutang ang imong code dinhi','Add %s' => 'Idugang ang %s','Remove' => 'Kuhaa','Order number and receipt will be sent to this email address.' => 'Ang numero sa order ug resibo ipadala sa kini nga email address.','Apartment, unit, building, floor, etc.' => 'Apartment, unit, building, salog, etc.','Shipping phone' => 'Telepono sa pagpadala','Only used for shipping-related questions.' => 'Gigamit ra alang sa mga pangutana nga may kalabotan sa pagpadala.','Single step' => 'Usa ka lakang','Click to go to the order summary' => 'I-klik aron makaadto sa summary sa order','Cart total:' => 'Total nga kariton:','Proceed to %s' => 'Padayon sa %s','Proceed to contact' => 'Padayon sa pagkontak','Proceed to shipping' => 'Padayon sa pagpadala','Proceed to billing' => 'Padayon sa pagsingil','Proceed to payment' => 'Padayon sa pagbayad','Shipping method' => 'Pamaagi sa pagpadala','Additional notes' => 'Dugang nga mga nota','Payment method' => 'Pamaagi sa pagbayad','Step %1$s of %2$s' => 'Lakang %1$s sa %2$s','Change: %s' => 'Kausaban: %s','Not selected yet.' => 'Wala pa gipili.','Same as shipping address' => 'Parehas sa adres sa pagpadala','Same as billing address' => 'Parehas sa billing address','Order summary' => 'Summary sa order','Edit cart' => 'I-edit ang kariton','Did you mean %s?' => 'Gipasabot ba nimo ang %s?','Change email address to: {suggestion-value}' => 'Usba ang email address ngadto sa: {suggestion-value}','This is a required field.' => 'Kini usa ka gikinahanglan nga field.','This is not a valid email address.' => 'Dili kini balido nga email address.','This field does not match the related field value.' => 'Kini nga field dili motakdo sa may kalabutan nga field value.','The CPF number "{cpf_number}" is invalid.' => 'Ang numero sa CPF nga &quot;{cpf_number}&quot; dili balido.','The CNPJ number "{cnpj_number}" is invalid.' => 'Ang numero sa CNPJ nga &quot;{cnpj_number}&quot; dili balido.','(Required)' => '(Gikinahanglan)','Checkout Header - Desktop' => 'Checkout Header - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Ipakita ang mga widget sa checkout header alang sa dagkong mga screen. Gipakita lamang kung gigamit ang checkout header sa plugin.','Checkout Header - Mobile' => 'Checkout Header - Mobile','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Ipakita ang mga widget sa ubos sa checkout header para sa mga mobile device. Gipakita lamang kung gigamit ang checkout header sa plugin.','Checkout Sidebar' => 'Checkout Sidebar','Display widgets on the checkout sidebar after the order summary.' => 'Ipakita ang mga widget sa checkout sidebar pagkahuman sa summary sa order.','Checkout Order Summary' => 'Sumaryo sa Order sa Checkout','Display widgets inside the order summary at the checkout page.' => 'Ipakita ang mga widget sa sulod sa summary sa order sa panid sa pag-checkout.','Checkout Below Place Order' => 'Checkout Ubos sa Place Order','Display widgets below the place order button at the checkout page.' => 'Ipakita ang mga widget sa ubos sa place order button sa checkout page.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Ipakita ang mga widget sa checkout footer. Gipakita lamang kung gigamit ang checkout footer sa plugin.','Classic' => 'Klasiko','Boxed' => 'Kahon','Split' => 'Nabahin','Minimalist' => 'Minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Fluid Checkout ug Delivery Date plugins ni CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Namatikdan namo nga imong gigamit ang mga plugins Delivery &amp; Pickup Date Time para sa WooCommerce (libre ug PRO) ni CodeRockz. Ang paghiusa sa kini nga mga plugin gibalhin sa Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Pag-upgrade sa PRO','Fluid Checkout database updated successfully' => 'Ang database sa Fluid Checkout malampuson nga na-update','The database changes where applied successfully.' => 'Ang database nagbag-o kung diin malampuson nga gigamit.','Dismiss' => 'Isalikway','Fluid Checkout database update' => 'Pag-update sa database sa Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Ang pipila ka mga pagbag-o sa database gikinahanglan. Sama sa bisan unsang pag-update, girekomenda namon nga <strong>magkuha ka usa ka hingpit nga backup sa imong website sa dili pa magpadayon</strong> .','Update database' => 'Pag-update sa database','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Ang Fluid Checkout dili compatible sa Divi Builder checkout layout','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Ang Fluid Checkout nanginahanglan sa klasiko nga WooCommerce shortcode-based nga porma sa pag-checkout aron molihok. Kung gigamit ang Divi Builder aron ipasadya ang hitsura ug pagbati sa panid sa pag-checkout, ang mga klasiko nga shortcode gipulihan sa mga naandan nga widget gikan sa Divi Builder alang sa matag bahin sa panid sa pag-checkout. Kini nga mga custom nga widgets dili compatible sa Fluid Checkout.</p><p> Palihug usba ang imong panid sa pag-checkout nga ilisan ang mga widget sa Divi Builder sa usa ka widget sa teksto nga adunay sulud nga shortcode <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'I-edit ang panid sa pag-checkout','Read the documentation.' => 'Basaha ang dokumentasyon.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Ang Germanized PRO multistep checkout feature kinahanglang i-disable kung gamiton ang Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Kung gigamit ang Fluid Checkout, ang multistep nga bahin gikan sa Germanized PRO plugin mahimong dili kinahanglan ug mahimong hinungdan sa <strong>kritikal nga mga sayup samtang nagproseso sa mga bag-ong order</strong> . Palihug disable ang Germanized PRO multistep checkout feature sa mga setting sa plugin.','Go to Germanized settings' => 'Lakaw ngadto sa Germanized nga mga setting','Thanks for choosing Fluid Checkout!' => 'Salamat sa pagpili sa Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Dugay na nimong gigamit ang plugin. Giunsa nimo kini gusto hangtod karon?<br> Palihug hatagi kami usa ka dali nga rating, gipasalamatan namon ang matag gamay nga feedback ug gidasig kami nga magpadayon sa pagpauswag sa plugin :)','Rate the plugin' => 'I-rate ang plugin','I need help!' => 'Nagkinahanglan ko ug tabang!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Ang pipila ka mga bahin sa WooCommerce Checkout Manager sa Quadlayers mahimong dili molihok sama sa gipaabut kung gamiton kini sa Fluid Checkout. Basaha <a href="%s">ang among dokumentasyon</a> para sa dugang impormasyon ug alternatibong solusyon.','Read documentation' => 'Basaha ang dokumentasyon','Don\'t show this again' => 'Ayaw kini ipakita pag-usab','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Dugang nga mga template sa disenyo','Optimized cart page' => 'Na-optimize nga panid sa cart','Optimized order received / thank you page' => 'Gi-optimize nga order nadawat / salamat nga panid','Edit cart contents at checkout page' => 'I-edit ang mga sulud sa cart sa panid sa pag-checkout','Account matching / user matching' => 'Pagpares sa account / pagpares sa user','Trust symbols on the cart and thank you pages' => 'Mga simbolo sa pagsalig sa kariton ug mga panid sa pasalamat','More positions for the coupon code on the checkout page' => 'Dugang nga mga posisyon para sa coupon code sa checkout page','International phone numbers' => 'Internasyonal nga mga numero sa telepono','Gift messages and packing slips' => 'Mga mensahe sa regalo ug mga packing slip','Local pickup and in-store collection' => 'Lokal nga pickup ug in-store nga koleksyon','EU-VAT Assistant' => 'Katabang sa EU-VAT','I already have it – Hide this offer' => 'Naa na nako - Tagoa kini nga tanyag','Activated' => 'Gi-activate','Address book' => 'Libro sa adres','Select an image' => 'Pagpili og hulagway','Cart layout' => 'Layout sa kariton','Cart optimizations' => 'Mga pag-optimize sa cart','Enable cart page optimizations' => 'I-enable ang pag-optimize sa cart page','Header and footer template' => 'Template sa header ug footer','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Gikontrol kung gamiton ba ang wala’y pagkabalda nga header ug footer sa panid o ipadayon ang aktibo nga header ug footer sa tema.','Distraction free header and footer' => 'Wala’y pagkabalda nga header ug footer','Theme\'s header and footer' => 'Ang ulohan ug footer sa tema','Cart elements' => 'Mga elemento sa kariton','Make the order summary stay visible on the cart page while scrolling' => 'Himua nga ang summary sa order magpabilin nga makita sa panid sa cart samtang nag-scroll','Coupon codes' => 'Mga code sa kupon','Hidden' => 'Gitagoan','Before the cart items section' => 'Sa wala pa ang seksyon sa mga butang sa cart','Inside the cart items section' => 'Sulod sa seksyon sa mga butang sa cart','After the cart items section' => 'Pagkahuman sa seksyon sa mga butang sa cart','Before the shipping section' => 'Sa wala pa ang seksyon sa pagpadala','After the shipping section' => 'Pagkahuman sa seksyon sa pagpadala','Before the order summary' => 'Sa wala pa ang order summary','Inside the order summary' => 'Sulod sa order summary','Before the order totals' => 'Sa wala pa ang order total','After the order totals' => 'Human sa total nga order','After the order summary' => 'Human sa summary sa order','Shipping' => 'Pagpadala','Select position where to display the shipping costs and calculator on the cart page.' => 'Pilia ang posisyon kung asa ipakita ang mga gasto sa pagpadala ug calculator sa panid sa cart.','Display as a cart section' => 'Ipakita isip seksyon sa kariton','Cross-sells' => 'Cross-sells','Select position where to display the cross-sells section on the cart page.' => 'Pilia ang posisyon kung asa ipakita ang cross-sells nga seksyon sa panid sa cart.','Before the cart actions' => 'Sa wala pa ang mga aksyon sa kariton','After the cart actions' => 'Pagkahuman sa mga aksyon sa kariton','Layout of cross-sell items on the cart page.' => 'Layout sa cross-sell nga mga butang sa panid sa cart.','Optimized horizontal cross-sells layout' => 'Na-optimize nga horizontal cross-sells layout','Theme\'s cross-sells layout' => 'Layout sa cross-sells sa tema','Number of cross-sell items to display on the cart page' => 'Gidaghanon sa cross-sell nga mga butang nga ipakita sa panid sa cart','Add widget areas to the cart page' => 'Idugang ang mga lugar sa widget sa panid sa cart','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Kini nga mga widget nga mga lugar gigamit aron makadugang mga simbolo sa pagsalig ug mga badge sa pagsalig sa panid sa cart.','Checkout' => 'Checkout','Checkout layout' => 'Layout sa checkout','Design template' => 'Disenyo nga template','Dark mode' => 'Dark mode','Enable dark mode' => 'I-enable ang dark mode','Logo image' => 'Hulagway sa logo','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Pagpili og usa ka hulagway nga ipakita sa checkout page header. Magamit ra kung gamiton ang wala’y kabaldahan nga header ug footer.','Header background color' => 'Kolor sa background sa ulohan','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Pagpili og kolor sa background alang sa ulohan sa panid sa pag-checkout. Magamit ra kung gamiton ang wala’y kabaldahan nga header ug footer.','HTML color value. ie: #f3f3f3' => 'Bili sa kolor sa HTML. ie: #f3f3f3','Page background color' => 'Kolor sa background sa panid','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Pagpili og kolor sa background alang sa panid sa pag-checkout. Ang kolor gipadapat sa elemento <em>sa lawas</em> .','Footer background color' => 'Kolor sa background sa footer','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Pagpili og kolor sa background alang sa footer sa panid sa pag-checkout. Magamit ra kung gamiton ang wala’y kabaldahan nga header ug footer.','Progress bar' => 'Pag-uswag bar','Display the checkout progress bar when using multi-step checkout layout' => 'Ipakita ang pag-uswag bar sa pag-checkout kung naggamit og multi-step nga layout sa pag-checkout','Make the checkout progress bar stay visible while scrolling' => 'Himoa nga ang checkout progress bar magpabilin nga makita samtang nag-scroll','Express checkout' => 'Express checkout','Enable the express checkout section' => 'I-enable ang express checkout nga seksyon','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Nagpakita sa ekspres nga seksyon sa pag-checkout sa pag-checkout kung ang gisuportahan nga mga ganghaan sa pagbayad adunay kini nga bahin.','Display express checkout buttons in one line for larger screens' => 'Ipakita ang express checkout button sa usa ka linya para sa mas dagkong mga screen','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ibaliwala ang dugang nga checkout nga gikinahanglan nga mga natad sa pagbayad sa usa ka compatible nga express checkout payment gateway','Make the order summary stay visible while scrolling' => 'Himua nga makita ang summary sa order samtang nag-scroll','Choose a background color for the order summary section.' => 'Pagpili og kolor sa background alang sa seksyon sa summary sa order.','Highlight the order totals row in the order summary table' => 'I-highlight ang han-ay sa total nga linya sa order summary table','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Labing mapuslanon kung ang seksyon sa summary sa order walay gipasiugda nga kolor sa background. Mahimo usab nga magamit sa Cart, Order Received ug View Order nga mga panid kung gigamit ang Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Link sa aksyon sa summary sa order sa pag-checkout.','Edit cart link' => 'I-edit ang link sa cart','Cart items count' => 'Giihap ang mga butang sa kariton','Link to shop page' => 'Link sa shop page','Cart items' => 'Mga butang sa kariton','Hide cart items errors at the checkout page' => 'Tagoa ang mga kasaypanan sa mga butang sa cart sa panid sa pag-checkout','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Ayaw ipakita ang mensahe sa mga kasaypanan sa mga butang sa cart sa ibabaw sa panid sa pag-checkout. Kung gisumite ang porma sa pag-checkout aron makompleto ang pagpalit, kini nga mga mensahe sa sayup kanunay nga ipakita.','Place order' => 'Ibutang ang order','Define the position to display "Place order" and terms checkbox section.' => 'Ipasabut ang posisyon aron ipakita ang &quot;Pag-order sa lugar&quot; ug seksyon sa checkbox sa mga termino.','Some options might not be compatible with some plugins and themes.' => 'Ang ubang mga kapilian mahimong dili uyon sa pipila ka mga plugins ug mga tema.','Below the payment section' => 'Ubos sa seksyon sa pagbayad','Below the order summary' => 'Ubos sa summary sa order','Both below the payment section and the order summary' => 'Pareho sa ubos sa seksyon sa pagbayad ug ang summary sa order','Add widget areas to the checkout page' => 'Idugang ang mga lugar sa widget sa panid sa pag-checkout','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Kini nga mga widget nga mga lugar gigamit aron makadugang mga simbolo sa pagsalig ug mga badge sa pagsalig sa panid sa pag-checkout.','Display the coupon codes section title' => 'Ipakita ang titulo sa seksyon sa mga code sa kupon','Select position where to display the coupon codes section on the checkout page.' => 'Pilia ang posisyon kung asa ipakita ang seksyon sa mga code sa kupon sa panid sa pag-checkout.','Before the checkout steps' => 'Sa wala pa ang mga lakang sa pag-checkout','As a substep before payment methods' => 'Ingon usa ka substep sa wala pa ang mga pamaagi sa pagbayad','As a substep after payment methods' => 'Ingon usa ka substep pagkahuman sa mga pamaagi sa pagbayad','Default button style' => 'Default nga estilo sa buton','"Add" link button' => '&quot;Add&quot; nga buton sa link','Checkout fields' => 'Mga natad sa pag-checkout','Optional fields' => 'Opsyonal nga mga natad','Hide optional fields behind a link button' => 'Tagoa ang opsyonal nga mga natad luyo sa buton sa link','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Girekomenda nga bantayan kini nga kapilian aron makunhuran ang gidaghanon sa mga bukas nga natad sa input, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">basaha ang panukiduki</a> .','Do not hide "Address line 2" fields behind a link button' => 'Ayaw itago ang &quot;Address line 2&quot; nga mga natad sa luyo sa usa ka link nga buton','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Girekomenda lamang kung gikinahanglan sa kadaghanan sa mga kustomer ang field nga &quot;Address line 2&quot;, o kung ang pagkuha sa husto nga adres sa pagpadala hinungdanon (pananglitan, kung naghatud sa pagkaon ug uban pang mga produkto nga madunot).','Billing address' => 'Adres sa pagsingil','Select position where to display the billing address section on the checkout page.' => 'Pilia ang posisyon kung asa ipakita ang seksyon sa adres sa pagsingil sa panid sa pag-checkout.','As a step before shipping' => 'Ingon usa ka lakang sa wala pa ipadala','As a sub-step before the shipping address section' => 'Ingon usa ka sub-lakang sa wala pa ang seksyon sa address sa pagpadala','As a sub-step after the shipping address section' => 'Ingon usa ka sub-lakang pagkahuman sa seksyon sa address sa pagpadala','As a step after shipping' => 'Ingon usa ka lakang pagkahuman sa pagpadala','As a sub-step before the payment section' => 'Ingon usa ka sub-lakang sa wala pa ang seksyon sa pagbayad','Force billing and shipping addresses to the same (single section)' => 'Pugsa ang pagsingil ug mga adres sa pagpadala sa parehas (usa ka seksyon)','Checkbox for "Same as shipping/billing address" checked by default' => 'Ang checkbox para sa &quot;Parehas sa adres sa pagpadala/pagsingil&quot; nga gisusi pinaagi sa default','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Ang checkbox nga &quot;Sama sa adres sa pagpadala&quot; magsugod nga gisusi pinaagi sa default kung ang seksyon sa adres sa pagpadala unang gipakita.<br> Ang checkbox nga &quot;Parehas sa adres sa pagsingil&quot; magsugod nga gisusi pinaagi sa default kung ang seksyon sa adres sa pagsingil una nga gipakita.<br> Girekomenda nga biyaan kini nga kapilian nga gisusi aron makunhuran ang gidaghanon sa mga bukas nga natad sa input sa pag-checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">basaha ang panukiduki</a> .','Highlight the billing address section in the checkout form' => 'I-highlight ang seksyon sa adres sa pagsingil sa porma sa pag-checkout','Shipping address' => 'Adres sa pagpadala','Highlight the shipping address section in the checkout form' => 'I-highlight ang seksyon sa address sa pagpadala sa porma sa pag-checkout','Shipping methods' => 'Mga pamaagi sa pagpadala','Choose in which position to display the shipping methods section.' => 'Pilia kung asa nga posisyon ipakita ang seksyon sa mga pamaagi sa pagpadala.','Before shipping address' => 'Sa wala pa ang adres sa pagpadala','After shipping address' => 'Pagkahuman sa adres sa pagpadala','Local pickup' => 'Lokal nga pickup','Removes shipping address section when a local pickup shipping method is selected.' => 'Pagtangtang sa seksyon sa address sa pagpadala kung gipili ang usa ka lokal nga pamaagi sa pagpadala sa pickup.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Ilisan ang adres sa pagpadala sa lokasyon sa pickup point kung gipili ang lokal nga paagi sa pagpadala sa pickup.','Choose which address to save as the shipping address for local pickup orders.' => 'Pilia kung unsang adres ang tipigan ingon nga adres sa pagpadala alang sa lokal nga mga order sa pagkuha.','Save the selected pickup location' => 'I-save ang gipili nga lokasyon sa pagkuha','Save same as the billing address' => 'I-save sama sa adres sa pagsingil','Do not save any shipping address' => 'Ayaw i-save ang bisan unsang adres sa pagpadala','Company name field for shipping address' => 'Natad sa ngalan sa kompanya alang sa adres sa pagpadala','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Usba ang visibility para sa ngalan sa kompanya nga field para sa shipping address nga seksyon sa checkout form.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Kung ang field gitakda nga &quot;opsyonal&quot;, nga mao ang default nga visibility state, walay mga pagbag-o nga magamit aron ang ubang mga plugins magamit sa bisan unsang mga pagbag-o nga ilang gikinahanglan.','Hidden (remove field)' => 'Gitago (kuhaa ang field)','Optional' => 'Opsyonal','Required' => 'Gikinahanglan','Add shipping phone field to the checkout form.' => 'Idugang ang field sa telepono sa pagpadala sa porma sa pag-checkout.','Choose in which step to display the shipping phone field.' => 'Pilia kung asa nga lakang ipakita ang field sa pagpadala sa telepono.','Contact step' => 'Lakang sa kontak','Billing phone' => 'Pagsingil sa telepono','Add billing phone field to the checkout form.' => 'Idugang ang field sa telepono sa pagsingil sa porma sa pag-checkout.','Choose in which step to display the billing phone field.' => 'Pilia kung asa nga lakang ipakita ang uma sa telepono sa pagsingil.','Show country code beside the flag' => 'Ipakita ang kodigo sa nasod tupad sa bandera','Show an example of a valid phone number inside phone fields' => 'Ipakita ang usa ka pananglitan sa usa ka balido nga numero sa telepono sa sulod sa mga natad sa telepono','Do not change placeholders' => 'Ayaw usba ang mga placeholder','Show if not defined' => 'Ipakita kung dili gihubit','Always show' => 'Ipakita kanunay','Order notes' => 'Mga nota sa pag-order','Define the visibility of the additional order notes field.' => 'Ipasabot ang visibility sa dugang nga order note field.','Gift options' => 'Mga kapilian sa regalo','Allow customers to add a gift message and other gift related options to the order.' => 'Tugoti ang mga kustomer nga makadugang ug mensahe sa regalo ug uban pang mga kapilian nga may kalabotan sa regalo sa order.','Display the gift message as part of the order details table instead of a separate section' => 'Ipakita ang mensahe sa regalo isip bahin sa talaan sa mga detalye sa order imbes nga lahi nga seksyon','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Kini nga opsyon makaapekto sa pahina sa pagkumpirma sa order (salamat nga panid) ug mga detalye sa pag-order sa mga panid sa account, email ug mga packing slip.','Account matching' => 'Pagpares sa account','Enable the account matching feature' => 'I-enable ang bahin sa pagpares sa account','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'I-asoy ang mga order sa bisita nga kustomer sa ilang kasamtangan nga account kung adunay usa ka account nga adunay mga detalye sa pagkontak sa kustomer.','Display message when an account exists with the email address provided' => 'Ipakita ang mensahe kung adunay usa ka account nga adunay gihatag nga email address','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Ilisan ang mga natad sa paghimo og account sa usa ka pahibalo ug kapilian sa pag-log in. Sa pipila ka mga konteksto, mahimo nga girekomenda nga biyaan kini nga kapilian aron mapanalipdan ang pribasiya sa mga kustomer.','Dashboard' => 'Dashboard','Integrations' => 'Mga panagsama','License keys' => 'Mga yawe sa lisensya','Visit our website for more information about our plugins and add-ons.' => 'Bisitaha ang among website alang sa dugang nga kasayuran bahin sa among mga plugins ug mga add-on.','Order pay page' => 'Pag-order sa bayad nga panid','Order pay' => 'Bayad sa order','Enable order pay page optimizations' => 'I-enable ang pag-optimize sa panid sa bayad sa order','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Gibag-o ang layout sa panid sa bayad sa order alang sa mga naglungtad nga mga order nga naghulat nga bayad gikan sa kustomer.','Add widget areas to the order pay page' => 'Idugang ang mga lugar sa widget sa panid sa bayad sa order','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Kini nga mga widget nga mga lugar gigamit aron makadugang mga simbolo sa pagsalig ug mga badge sa pagsalig sa panid sa bayad sa order.','Thank you page & order details layout' => 'Salamat page ug mga detalye sa order layout','Order details optimizations' => 'Pag-optimize sa mga detalye sa order','Enable thank you page and order details optimizations' => 'I-enable ang pahina sa pasalamat ug pag-optimize sa mga detalye sa order','Changes the layout of order details on the thank you page and account pages.' => 'Gibag-o ang layout sa mga detalye sa order sa panid sa pasalamat ug mga panid sa account.','Enable order details customizations on email notifications' => 'I-enable ang mga pag-customize sa mga detalye sa order sa mga pahibalo sa email','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Ipakita ang bag-ong mga seksyon ug usba ang han-ay sa mga seksyon sa mga pahibalo sa email. Ang mga istilo sa mga detalye sa order sa mga pahibalo sa email nagpabilin nga wala mausab.','Thank you page' => 'Salamat page','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Kini nga mga kapilian makaapekto sa salamat nga panid, nailhan usab nga nadawat nga order o mga panid sa pagkumpirma sa order.','Order details layout' => 'Layout sa mga detalye sa order','Display the order details with wide layout on the thank you page' => 'Ipakita ang mga detalye sa order nga adunay lapad nga layout sa panid sa salamat','Add widget areas to the thank you page' => 'Idugang ang mga lugar sa widget sa panid sa pasalamat','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Kini nga mga widget nga mga lugar gigamit aron makadugang mga simbolo sa pagsalig ug mga badge sa pagsalig sa panid sa salamat.','Order actions' => 'Pag-order sa mga aksyon','Choose in which position to display the order actions.' => 'Pilia kung asa nga posisyon ipakita ang order nga mga aksyon.','Inside the order overview' => 'Sulod sa overview sa order','After the order overview' => 'Pagkahuman sa overview sa order','After order sections' => 'Pagkahuman sa mga seksyon sa pag-order','Order status' => 'Status sa order','Display the order status progress bar' => 'Ipakita ang status sa order progress bar','Choose in which position to display the section.' => 'Pilia kung asa nga posisyon ipakita ang seksyon.','After the order overview and payment instructions' => 'Pagkahuman sa overview sa order ug mga panudlo sa pagbayad','Before the order items section' => 'Sa wala pa ang seksyon sa mga butang sa pag-order','Inside the order items section' => 'Sulod sa seksyon sa mga butang sa pag-order','After the order items section' => 'Pagkahuman sa seksyon sa mga butang sa pag-order','On the sidebar' => 'Sa sidebar','Order downloads' => 'Pag-order sa mga pag-download','Gift message' => 'Mensahe sa regalo','Tools' => 'Mga galamiton','Troubleshooting' => 'Pag-troubleshoot','Debug options' => 'Mga kapilian sa pag-debug','Debug mode' => 'Debug mode','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Ang paggamit sa debug mode makaapekto sa performance sa website. Gamita lang kini nga opsyon samtang nag-troubleshoot.','Load unminified assets' => 'Pag-load sa wala giminusan nga mga kabtangan','Enhanced select fields' => 'Gipalambo nga pinili nga mga natad','Fix automatic zoom-in on form fields' => 'Ayuhon ang awtomatik nga pag-zoom-in sa mga natad sa porma','Set <code>font-size</code> inside form fields to 16px' => 'Ibutang <code>font-size</code> sulod sa mga field sa porma ngadto sa 16px','Fluid Checkout' => 'Pagsusi sa Fluid','Settings' => 'Mga setting','Support' => 'Suporta','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Pag-upgrade sa PRO</a> aron maablihan ang daghang mga kapilian.','(PRO)' => '(PRO)','(experimental)' => '(eksperimento)','Please verify your phone number.' => 'Palihug pamatud-i ang imong numero sa telepono.','The Bluehost Plugin' => 'Ang Bluehost Plugin','Custom fields' => 'Custom nga mga natad','Enable custom shipping email field' => 'I-enable ang custom shipping email field','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Kung mahimo, ang field sa pagpadala sa email gikan sa Bluehost plugin idugang sa porma sa pag-checkout.','Captcha Pro by BestWebSoft' => 'Captcha Pro pinaagi sa BestWebSoft','Captcha position' => 'Posisyon sa Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Ipasabut ang posisyon aron ipakita ang seksyon sa captcha. Ang ubang mga posisyon mahimong dili molihok depende sa captcha type nga gipili.','Selecting a pickup point is required before proceeding.' => 'Kinahanglan ang pagpili og pickup point sa dili pa mopadayon.','Pickup point' => 'Pickup point','Pickup point not selected yet.' => 'Wala pa mapili ang pickup point.','Pickup point:' => 'Pickup point:','Mailchimp for WooCommerce' => 'Mailchimp alang sa WooCommerce','Subscribe checkbox' => 'Mag-subscribe nga checkbox','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'I-override ang posisyon alang sa checkbox sa pag-subscribe sa panid sa pag-checkout ug ipakita kini kanunay sa lakang sa pagkontak','Before Shipping Address' => 'Sa wala pa ang Address sa Pagpadala','(originally "%s")' => '(orihinal nga &quot;%s&quot;)','After Shipping Address' => 'Human sa Address sa Pagpadala','Selecting a collection point is required when shipping with FermoPoint.' => 'Ang pagpili sa usa ka punto sa pagkolekta gikinahanglan kung ipadala gamit ang FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Kung gisusi nagpahibalo sa mga typo sa email sa mga tiggamit. (Kini nga feature gi-disable tungod kay ang Fluid Checkout nagtanyag sa feature. Ang mga kausaban niini nga opsyon dili mo-epekto)','Enable Mail Check: (disabled feature)' => 'I-enable ang Mail Check: (nawala nga bahin)','Carrier:' => 'Tigdala:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce Email Marketing','Sign up checkbox position' => 'Pag-sign up sa posisyon sa checkbox','Move the sign up checkbox to the contact step' => 'Ibalhin ang checkbox sa pag-sign up sa lakang sa pagkontak','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Kung mahimo, ang checkbox ibalhin sa lakang sa kontak nga independente sa lokasyon sa gipakita nga gitakda sa mga setting sa Sendinblue plugin.','Theme Betheme' => 'Tema nga Betheme','Checkout progress' => 'Pag-uswag sa checkout','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa Betheme sa checkout, cart ug order nga nadawat nga mga panid.','Theme Fennik' => 'Tema nga Fennik','Breadcrumbs' => 'Mga mumho sa pan','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'I-output ang seksyon sa mga breadcrumb gikan sa tema sa Fennik kon gamiton ang Fluid Checkout header ug footer.','Theme Go' => 'Lakaw sa Tema','My account layout' => 'Layout sa akong account','Enable wide layout on "My account" page.' => 'I-enable ang lapad nga layout sa &quot;Akong account&quot; nga panid.','Theme Impreza' => 'Tema nga Impreza','Header' => 'Ulohan','Spacing for site header at the checkout page (in pixels)' => 'Spacing para sa site header sa checkout page (sa pixels)','Only applicable when using the Impreza theme header at the checkout page.' => 'Magamit ra kung gamiton ang header sa tema sa Impreza sa panid sa pag-checkout.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa tema sa Kapee sa checkout, cart ug order nga nadawat nga mga panid.','Theme Porto' => 'Tema nga Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa tema sa Porto sa checkout, cart ug order nga nadawat nga mga panid.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa tema sa Pressmart sa checkout, cart ug order nga nadawat nga mga panid.','Theme The Gem' => 'Tema Ang Mutya','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa tema nga The Gem kung gigamit ang Fluid Checkout header ug footer.','Theme Woodmart' => 'Tema nga Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa tema sa Woodmart kung gamiton ang header ug footer sa Fluid Checkout.','Checkout options' => 'Mga kapilian sa pag-checkout','Disable the theme checkout options' => 'I-disable ang mga opsyon sa pag-checkout sa tema','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Ang mga opsyon nga nagpakita sa hulagway sa produkto, natad sa gidaghanon, kuhaa ang buton ug ang link sa panid sa produkto nga gidugang sa tema gi-disable pinaagi sa default.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Pag-uswag sa order','Display order progress from the theme' => 'Ipakita ang pag-uswag sa han-ay gikan sa tema','Display the form field labels visible on the page' => 'Ipakita ang porma nga mga label sa field nga makita sa panid','It is recommended to keep this option enabled for a better user experience.' => 'Girekomenda nga ipadayon kini nga kapilian nga magamit alang sa usa ka labi ka maayo nga kasinatian sa tiggamit.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Idugang ang dugang nga mga natad sa porma sa pag-checkout','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Nagdugang usa ka dugang nga email sa pagpadala ug natad sa telepono sa pagpadala sa seksyon sa address sa pagpadala.','Go to the home page' => 'Adto sa home page','Skip to content' => 'Laktaw sa sulod','Create an account' => 'Paghimo og account','Log in to your account' => 'Log in sa imong account','Already have an account?' => 'Naa na kay account?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Naka-log in isip %1$s. <a href="%2$s">Log out</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Ang imong order adunay kinatibuk-ang kantidad sa %s. Wala nay dugang nga bayad ang gikinahanglan.','Close and continue with checkout' => 'Pagsira ug pagpadayon sa pag-checkout','Continue' => 'Padayon','Parcel terminal' => 'Terminal sa parsela','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Kini nga widget gipulihan sa Fluid Checkout.</p><p> Kung gigamit ang Fluid Checkout, ang panid sa pag-checkout kinahanglan nga mogamit sa orihinal nga WooCommerce shortcode <code>[woocommerce_checkout]</code> aron molihok sa husto.</p><p> Para sa dugang nga impormasyon, bisitaha ang Fluid Checkout nga dokumentasyon.</p>','Theme The7' => 'Tema Ang7','Additional header sections' => 'Dugang nga mga seksyon sa ulohan','Output additional header sections if enabled in the theme settings.' => 'Pag-output og dugang nga mga seksyon sa header kung mahimo sa mga setting sa tema.','More information' => 'Dugang impormasyon','Pick a Locker' => 'Pagpili ug Locker','Page template' => 'Panid template','Use `Order confirmation` page template for block-based themes' => 'Gamita ang template sa panid sa `Pagkumpirma sa order` alang sa mga tema nga gibase sa block','Only applies when using a block-based theme.' => 'Magamit ra kung mogamit usa ka tema nga nakabase sa block.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Porma sa pagbayad','Apply styles to the Stripe payment form fields' => 'Ibutang ang mga istilo sa mga field sa porma sa pagbayad sa Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Kung mahimo, ang Fluid Checkout mag-aplay sa mga istilo nga na-optimize alang sa pagkaangay sa plugin. Mahimo nimong i-disable kini kung naggamit ka mga kostumbre nga istilo alang sa mga natad sa porma sa pagbayad sa Stripe.','Theme Nyture' => 'Tema nga Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa tema nga Nyture kung gamiton ang Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Gitugotan ang mga kostumer nga magbayad alang sa mga order nga gihimo nga mano-mano sa admin sa tindahan o wala makompleto sa panahon sa pag-checkout.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Ang plugin nga WooCommerce Checkout Manager ni Quadlayers dili compatible sa Fluid Checkout','Company name field for billing address' => 'Natad sa ngalan sa kompanya alang sa adres sa pagsingil','Change visibility for the company name field for the billing address section on the checkout form.' => 'Usba ang visibility para sa ngalan sa kompanya nga field para sa billing address section sa checkout form.','Theme Bookshelf' => 'Tema nga Estante sa Libro','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'I-output ang seksyon sa mga lakang sa pag-checkout gikan sa tema sa Bookshelf kung gamiton ang Fluid Checkout.','Account password' => 'Password sa account','An account will be created with the information provided at checkout when completing the order.' => 'Ang usa ka account pagabuhaton uban sa impormasyon nga gihatag sa checkout sa diha nga ang pagkompleto sa order.','Choose the style of the progress bar.' => 'Pilia ang estilo sa progress bar.','Bars' => 'Mga bar','Theme Ireca' => 'Tema nga Ireca','WooCommerce page layout' => 'Layout sa panid sa WooCommerce','Force wide layout on WooCommerce pages' => 'Puwersa ang lapad nga layout sa mga panid sa WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Gisiguro niini nga ang seksyon sa sulud dili kaayo pig-ot sa mga panid sa WooCommerce lakip ang pag-checkout, cart, nadawat nga order, bayad sa order ug mga panid sa account.','WooCommerce Smart Coupons' => 'WooCommerce Smart Kupon','Position on checkout page' => 'Posisyon sa panid sa pag-checkout','Choose where to display the available coupons section on the checkout page.' => 'Pilia kung asa ipakita ang magamit nga seksyon sa mga kupon sa panid sa pag-checkout.','Before the progress bar' => 'Sa wala pa ang progress bar','After the progress bar' => 'Pagkahuman sa progress bar','Before coupon codes section' => 'Sa wala pa ang seksyon sa mga code sa kupon','Format phone numbers according to the rules for each country.' => 'I-format ang mga numero sa telepono sumala sa mga lagda alang sa matag nasud.','Use precise phone number validation' => 'Gamita ang tukma nga pag-validate sa numero sa telepono','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Kini usa ka eksperimento nga bahin ug mahimong dili molihok sama sa gipaabut sa tanan nga mga setup. Gamita kini uban ang pag-amping.','Phone number validation types used when precise validation is enabled.' => 'Ang mga tipo sa pag-validate sa numero sa telepono nga gigamit kung ang tukma nga pag-validate gipagana.','Mobile' => 'Mobile','Fixed line' => 'Naayo nga linya','Toll free' => 'Libre ang bayad','Contact' => 'Kontaka','Multi step' => 'Daghang lakang','2 columns' => '2 ka kolum','1 column' => '1 ka kolum','Before checkout steps' => 'Sa dili pa ang mga lakang sa pag-checkout','Or' => 'O','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Kon gamiton ang <em>&quot;1 column&quot;</em> checkout layout, kini nga opsyon kanunay nga naka-set sa <em>&quot;Before checkout steps&quot;</em> ug magamit usab sa desktop view.','Position for the extra order summary section on mobile.' => 'Posisyon para sa seksyon sa dugang nga summary sa order sa mobile.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Ang opsyon nga <em>&quot;On the site header&quot;</em> magamit lang kon gamiton ang distraction-free header.','On the site header (requires distraction-free header)' => 'Sa header sa site (nanginahanglan og header nga walay makabalda)','Initial state for the expansible order summary section on mobile.' => 'Inisyal nga kahimtang para sa mapalapad nga seksyon sa summary sa order sa mobile.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Among girekomendar nga ibutang kini isip <em>gipalapdan</em> para sa mosunod nga mga nasud tungod sa mga kinahanglanon sa regulasyon: <strong>Germany</strong> , <strong>Austria</strong> , <strong>Switzerland</strong> , <strong>Netherlands</strong> , <strong>Poland</strong> , <strong>Belgium</strong> ug <strong>France</strong> .','Collapsed' => 'Nahugno','Expanded' => 'Gipalapdan','Do not show' => 'Ayaw ipakita','yes' => 'oo','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Ang field sa numero sa telepono sa pagpadala mahimong mapugos nga &quot;gikinahanglan&quot; kon ang seksyon sa adres sa pagbayad gipakita human sa seksyon sa adres sa pagpadala, ug ang field sa numero sa telepono sa pagbayad gibutang nga &quot;gikinahanglan&quot;. Kinahanglan kini aron masiguro nga ang adres sa pagpadala makopya ngadto sa adres sa pagbayad kon kini nga opsyon gisusi, kay kon dili, ang kustomer mahimong dili makakompleto sa porma sa pag-checkout.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Ang field sa billing phone mahimong mapugos nga &quot;gikinahanglan&quot; kon ang seksyon sa billing address gipakita sa dili pa ang seksyon sa shipping address, ug ang field sa shipping phone gibutang nga &quot;gikinahanglan&quot;. Kinahanglan kini aron masiguro nga ang shipping address makopya ngadto sa billing address kon masusi kana nga opsyon, kay kon dili, ang kustomer mahimong dili makakompleto sa checkout form.','Settings profiles' => 'Mga profile sa setting','Settings profile' => 'Profile sa mga setting','You do not have permission to perform this action.' => 'Wala kay permiso sa paghimo niini nga aksyon.','You do not have permission to activate plugins.' => 'Wala kay permiso sa pag-activate sa mga plugin.','Missing plugin.' => 'Nawala nga plugin.','Plugin activated.' => 'Gi-aktibo ang plugin.','The following changes will be applied:' => 'Ang mosunod nga mga pagbag-o ipadapat:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Sukad sa Fluid Checkout 5.0, ang mga setting lahi na ang pagka-save. Ang mga legacy option gitipigan gihapon sa database aron tugotan ang pag-downgrade sa mga naunang bersyon kon gikinahanglan.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Ang imong tindahan nagdagan na sulod sa mga 2 ka semana gamit ang bag-ong mga setting aron malimpyohan nimo ang mga legacy nga opsyon nga gitipigan sa database. Palihug timan-i nga human sa paglimpyo, kung kinahanglan nimo nga mag-downgrade sa mga naunang bersyon sa plugin, mogamit kini og mga default nga kantidad para sa tanang setting.','Fluid Checkout settings cleanup' => 'Paglimpyo sa mga setting sa Fluid Checkout','Delete leftover options' => 'Tangtanga ang mga nahibiling opsyon','Help us improve Fluid Checkout' => 'Tabangi kami nga mapaayo ang Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Ipaambit ang mga anonymous nga report sa palibot sa site sa Fluid Checkout aron makakuha og mas paspas nga suporta ug matabangan kami nga mapaayo ang pagkaangay ug masukod ang epekto. Walay kustomer, tiggamit, o sensitibo nga datos nga gilakip. Mahimo nimong pilion kung unsa ang ipaambit bisan unsang orasa gikan sa mga setting sa Tools.','Enable site environment reports' => 'I-enable ang mga report sa palibot sa site','Review settings' => 'Ribyuha ang mga setting','This preview has expired. Reload the admin page to start a new preview.' => 'Kini nga preview wala na magamit. I-reload ang admin page aron magsugod og bag-ong preview.','Preview expired' => 'Natapos na ang preview','Orders cannot be placed in the preview.' => 'Dili mahimo ang mga order sa preview.','Logging in is not available in the preview.' => 'Dili magamit ang pag-log in sa preview.','Accounts cannot be created in the preview.' => 'Dili makahimo og mga account sa preview.','Requests to other sites are blocked in the preview.' => 'Ang mga hangyo ngadto sa ubang mga site gibabagan sa preview.','Processing…' => 'Giproseso…','Something went wrong. Please try again.' => 'Adunay nahitabo nga sayop. Palihug sulayi pag-usab.','Activate plugin' => 'I-aktibo ang plugin','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Ang kompletong pakete sa checkout','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Tanang PRO features + tanang add-ons, usa ra ka presyo. Mga template sa disenyo, gi-optimize nga mga panid sa cart ug order received, pagpares sa account, ug daghan pa.','Optimized order pay page' => 'Gi-optimize nga panid sa pagbayad sa order','Express checkout buttons from supported payment methods' => 'Mga buton sa express checkout gikan sa gisuportahan nga mga pamaagi sa pagbayad','Delayed account creation' => 'Nalangan nga paghimo og account','Address autocomplete with Google Maps APIs' => 'Awtomatikong pagkompleto sa adres gamit ang Google Maps APIs','Multiple saved addresses with the address book' => 'Daghang na-save nga mga adres gamit ang address book','EU-VAT assistant' => 'Katabang sa EU-VAT','Hide this section' => 'Itago kini nga seksyon','Learn more' => 'Pagkat-on og dugang','Get early access' => 'Pagkuha og sayo nga access','Activate add-on' => 'I-aktibo ang add-on','Get more out of your checkout journey' => 'Pahimusli ang dugang benepisyo sa imong panaw sa pag-checkout','Test API key' => 'Sulayan ang yawe sa API','Guided setup' => 'Gigiyahan nga pag-setup','Options' => 'Mga Opsyon','Set up layout and design on the <a href="%s">checkout options</a>.' => 'I-set up ang layout ug disenyo sa <a href="%s">mga opsyon sa checkout</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'I-enable ang guest checkout ug/o ribyuha <a href="%s">ang mga setting sa account sa kustomer</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'I-enable ang na-optimize nga mga panid <a href="%1$s">sa cart</a> , <a href="%2$s">salamat</a> ug <a href="%3$s">pagbayad sa order</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'I-enable <a href="%s">ang autocomplete sa address</a> gikan sa Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'I-enable ang daghang na-save nga mga adres gamit ang <a href="%s">address book</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Susiha kon aduna bay <a href="%s">mga opsyon sa integrasyon</a> nga magamit para sa tema o uban pang mga plugin nga imong gi-install.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Pagkuha og mas paspas nga suporta ug tabangi kami sa pagpalambo sa pagkaangay ug pagsukod sa epekto. <a href="%s">I-enable ang pagsubay sa paggamit</a> gikan sa mga setting sa himan.','Missing settings tab.' => 'Nawala ang tab sa mga setting.','Getting started' => 'Pagsugod','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Maayo! Ang imong checkout page nagdagan na karon sa Fluid Checkout.</strong> Ania ang pipila ka mga lakang aron makasugod:','Completed' => 'Nahuman na','Preview report data' => 'I-preview ang datos sa report','Send now' => 'Ipadala karon','Auto-detect' => 'Awtomatikong mamatikdan','Afrikaans' => 'Afrikaans','Albanian' => 'Albanian','Amharic' => 'Amharic','Arabic' => 'Arabiko','Armenian' => 'Armenian','Azerbaijani' => 'Azerbaijani','Basque' => 'Basque','Belarusian' => 'Belarusian','Bengali' => 'Bengali','Bosnian' => 'Bosnian','Bulgarian' => 'Bulgarian','Burmese' => 'Burmese','Catalan' => 'Katalan','Chinese' => 'Intsik','Chinese (Simplified)' => 'Intsik (Gipasimple)','Chinese (Hong Kong)' => 'Intsik (Hong Kong)','Chinese (Traditional)' => 'Intsik (Tradisyonal)','Croatian' => 'Kroato','Czech' => 'Czech','Danish' => 'Danish','Dutch' => 'Olandes','English' => 'Ingles','English (Australian)' => 'Ingles (Australyano)','English (Great Britain)' => 'Ingles (Grande Britanya)','Estonian' => 'Estonian','Farsi' => 'Parsi','Finnish' => 'Pinlandes','Filipino' => 'Pilipino','French' => 'Pranses','French (Canadian)' => 'Pranses (Canadian)','Galician' => 'Galician','Georgian' => 'Georgian','German' => 'Aleman','Greek' => 'Griyego','Gujarati' => 'Gujarati','Hebrew' => 'Hebreo','Hindi' => 'Hindi','Hungarian' => 'Hungariano','Icelandic' => 'Icelandic','Indonesian' => 'Indones','Italian' => 'Italyano','Japanese' => 'Hapon','Kannada' => 'Kannada','Kazakh' => 'Kazakh','Khmer' => 'Khmer','Korean' => 'Koreano','Kyrgyz' => 'Kirghiz','Lao' => 'Lao','Latvian' => 'Latviano','Lithuanian' => 'Lithuanian','Macedonian' => 'Macedonian','Malay' => 'Malayo','Malayalam' => 'Malayalam','Marathi' => 'Marathi','Mongolian' => 'Mongolian','Nepali' => 'Nepali','Norwegian' => 'Norwegian','Polish' => 'Polish','Portuguese' => 'Portuges','Portuguese (Brazil)' => 'Portuges (Brazil)','Portuguese (Portugal)' => 'Portuges (Portugal)','Punjabi' => 'Punjabi','Romanian' => 'Romaniano','Russian' => 'Ruso','Serbian' => 'Serbiano','Sinhalese' => 'Sinhalese','Slovak' => 'Eslobako','Slovenian' => 'Eslobenyano','Spanish' => 'Kinatsila','Spanish (Latin America)' => 'Kinatsila (Latin America)','Swahili' => 'Swahili','Swedish' => 'Sweko','Tamil' => 'Tamil','Telugu' => 'Telugu','Thai' => 'Thai','Turkish' => 'Turko','Ukrainian' => 'Ukrainiano','Urdu' => 'Urdu','Vietnamese' => 'Vietnamese','Zulu' => 'Zulu','Google address autocomplete' => 'Awtomatikong pagkompleto sa adres sa Google','Google Places API version' => 'Bersyon sa Google Places API','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Pilia kung unsang bersyon sa Google Places API ang gamiton. Among girekomendar ang pagbalhin ngadto sa bag-ong Places API sa labing madali.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Among girekomendar ang paggamit sa &quot;Places API (Bag-o)&quot; sugod Marso 1, 2025. Ibalhin sa Google ang bersyon nga &quot;Places API (Legacy)&quot; ngadto sa Legacy status, buot ipasabot nga dili na nimo ma-enable kini nga serbisyo para sa mga bag-ong API key ug kana nga bersyon sa API sa ngadto-ngadto dili na magamit. Ang mga kasamtangang account nga naggamit na sa Legacy API mahimong magpadayon sa pagtrabaho nga walay mga pagkabalda.','(Recommended)' => '(Girekomenda)','Google API key' => 'Yawe sa Google API','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Idikit ang imong Google API key ug gamita ang test button aron kumpirmahon nga kini mogana para niini nga website. Siguruha nga ang key balido ug gitugot para sa imong domain, kay kon dili, ang address field mahimong mababagan nga makapugong sa mga kustomer sa pagkompleto sa ilang mga order.','Enable Google address autocomplete' => 'I-enable ang awtomatikong pagkompleto sa adres sa Google','Enable address autocompletion using the Google Maps APIs.' => 'I-enable ang autocompletion sa address gamit ang Google Maps APIs.','Google API language' => 'Pinulongan sa Google API','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Kini nga pinulongan gamiton aron ipakita ang mga sugyot sa adres sa Google Places API ug ang mga adres awtomatiko usab nga makompleto niini nga pinulongan.','Result types' => 'Mga klase sa resulta','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Pasagdi nga walay sulod aron modawat og bisan unsang klase sa resulta, nga kasagaran mohatag og mas maayong mga resulta nga motakdo. <a href="%s" target="_blank">Tan-awa ang dokumentasyon alang sa dugang detalye</a> .<br> Pagpili hangtod sa 5 ka klase sa resulta sa pagpangita sa adres aron ibalik sa mga field nga awtomatikong kompletohon ang adres.<br> Bisitaha ang dokumentasyon sa Google Maps aron mahibal-an ang dugang bahin sa <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">gisuportahan nga mga tipo</a> .','Result types (Legacy API)' => 'Mga klase sa resulta (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Unsang klase sa resulta sa pagpangita sa address ang ibalik kon gamiton ang Places API (Legacy).<br> Bisitaha ang dokumentasyon sa Legacy Google Places API aron mahibal-an ang dugang bahin sa <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">gisuportahan nga mga tipo</a> .','Company fields' => 'Mga natad sa kompanya','Enable autocomplete for the company name if available' => 'I-enable ang autocomplete para sa ngalan sa kompanya kon anaa','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'I-enable ang autocompletion sa company field nga adunay impormasyon sa ngalan sa kompanya kon ibalik gikan sa Google Maps APIs.','Business search' => 'Pagpangita sa negosyo','Enable search for businesses in the company field' => 'I-enable ang pagpangita og mga negosyo sa field sa kompanya','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'I-enable ang sugyot sa mga adres nga nalangkit sa usa ka negosyo kon mag-type sa field sa kompanya, dayon i-autocomplete ang tanang field sa adres kon ang usa ka negosyo mapili gikan sa mga sugyot.','Company result types' => 'Mga klase sa resulta sa kompanya','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Pagpili hangtod sa 5 ka klase sa resulta sa pagpangita sa adres nga ibalik sa mga field sa kompanya nga awtomatikong kompletohon.<br> Ang girekomendar nga kantidad mao ang <code>establishment</code> , nga naglakip sa kadaghanan sa mga klase sa negosyo.<br> Pasagdi nga blangko aron modawat og bisan unsang klase sa resulta, lakip na ang mga resulta nga walay kalabotan sa mga negosyo.<br> Bisitaha ang dokumentasyon sa Google Maps aron mahibal-an ang dugang bahin sa <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">gisuportahan nga mga tipo</a> .','Google logo' => 'Logo sa Google','Show text and logo "Powered by Google"' => 'Ipakita ang teksto ug logo nga &quot;Powered by Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Kon ma-tsek, ang teksto ug logo nga &quot;Powered by Google&quot; ipakita sa ubos sa kahon sa mga sugyot sa autocomplete sa address.','Brasil API address autocomplete' => 'Awtomatikong pagkompleto sa adres sa Brasil API','Brasil API' => 'Brasil API','Enable Brasil API address autocomplete for CEP fields' => 'I-enable ang Brasil API address autocomplete para sa mga CEP field','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Gamita ang Brasil API aron makuha ug ma-autofill ang mga adres gamit ang CEP/Postcode field. May kalabotan lang kini sa mga adres sa Brazil.','API version' => 'Bersyon sa API','Choose which version of the Brasil API CEP method to use.' => 'Pilia kung unsang bersyon sa Brasil API CEP nga pamaagi ang gamiton.','Address book migration' => 'Pagbalhin sa libro sa adres','WooCommerce addresses' => 'Mga adres sa WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopyaha ang kasamtangang mga adres sa pagpadala ug pagsingil gikan sa WooCommerce ngadto sa address book sa mga kustomer.','Enable the address book feature' => 'I-enable ang feature sa address book','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Tugoti ang mga kustomer sa pag-save sa daghang mga adres ug pagtino sa default nga adres nga gamiton alang sa pagpadala ug pagsingil.','Address labels' => 'Mga label sa adres','Allow customers to add a custom label for each address' => 'Tugoti ang mga kustomer sa pagdugang og custom label para sa matag address','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Ang mga label sa adres makapasayon sa mga kustomer sa pag-ila sa ilang na-save nga mga adres (pananglitan: &quot;Balay ni Mama&quot;). Pribado ang mga label sa adres para sa mga kustomer, ug dili kini ipakita o i-imprinta sa panid sa mga detalye sa order o mga invoice.','Display layout' => 'Layout sa pagpakita','Choose how saved addresses are displayed at checkout and on the cart.' => 'Pilia kon unsaon pagpakita ang mga na-save nga address sa checkout ug sa cart.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Magamit sa checkout ug sa cart. Ang mga na-save nga address sa panid sa account kanunay mogamit sa layout sa mga kard.','Address cards' => 'Mga kard sa adres','Address list' => 'Lista sa adres','Dropdown field' => 'Dropdown nga natad','Address search' => 'Pagpangita og adres','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Ipakita ang filter sa pagpangita sa address sa frontend kung ang kustomer adunay labing menos kini nga gidaghanon sa mga na-save nga address nga magamit.','Not used when display layout is set to dropdown field.' => 'Dili gamiton kon ang display layout gibutang sa dropdown field.','Addresses' => 'Mga Address','Enable cart page optimizations to see more options' => 'I-enable ang mga pag-optimize sa panid sa cart aron makakita og dugang mga kapilian','Sticky order summary' => 'Sumaryo sa sticky order','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Pilia ang posisyon diin ipakita ang seksyon sa mga coupon code sa panid sa cart. Magamit lang kini kung ang AJAX cart naka-enable, ug kung ang paggamit sa mga coupon code naka-enable sa mga setting sa WooCommerce.','Layout of cross-sell' => 'Layout sa cross-sell','Cross-sells displayed' => 'Gipakita ang mga cross-sell','Items' => 'Mga butang','Cart page optimization' => 'Pag-optimize sa panid sa cart','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Hatagi ang imong cart sa parehas nga klaro, naka-focus sa conversion nga layout sama sa imong checkout.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Ipares ang layout sa cart sa checkout page para sa makanunayon nga proseso sa pagpalit.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Ipadayon nga kanunay nga updated ang cart sa background, walay pag-reload sa tibuok panid kung mausab ang gidaghanon.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Ibutang ang mga coupon code, shipping, ug cross-sell kung asa gyud kini labing maayo nga mo-convert.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Ipadayon nga makita ang summary sa order samtang nag-scroll, ug idugang ang mga simbolo sa pagsalig kung diin ang mga mamalitay nanginahanglan og pasalig.','Columns' => 'Mga Kolum','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Kinatibuk-ang mga estilo para sa mga lakang sa pag-checkout, summary sa order ug uban pang mga seksyon. Magamit sa ubang pag-checkout, cart, salamat (nadawat nga order), ug pagtan-aw sa mga panid sa order.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Kon gamiton ang layout nga <em>&quot;1 column&quot;</em> uban sa template sa disenyo <em>nga &quot;Split&quot;</em> , ang tuo nga kolum makita lang kon aktibo ang widget area sa sidebar sa panid (Checkout Sidebar, Cart Sidebar, o Order Received Sidebar). Kon dili, ang panid magpabilin nga usa ka kolum nga adunay Split styles.','Split column background' => 'Background sa nabahin nga kolum','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Pagpili og kolor sa background para sa ikaduhang kolum sa Split design. Pasagdi nga blangko aron magamit ang kolor sa background sa summary sa order.','Page templates' => 'Mga template sa panid','Checkout template' => 'Template sa pag-checkout','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Girekomendar para sa mas gamay nga makabalda sa checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Basaha ang panukiduki bahin sa pagbiya sa cart</a> .','Sticky progress bar' => 'Malagkit nga progress bar','Progress bar style' => 'Estilo sa progress bar','Order totals' => 'Kinatibuk-ang order','Background color' => 'Kolor sa background','Action link' => 'Link sa aksyon','Mobile order summary' => 'Sumaryo sa order sa mobile','Mobile initial state' => 'Inisyal nga kahimtang sa mobile','Enable editing cart items at checkout' => 'I-enable ang pag-edit sa mga butang sa cart sa checkout','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Tugoti ang mga kustomer sa pag-usab sa gidaghanon sa produkto o pagtangtang sa mga butang direkta sa panid sa checkout.','Cart item errors' => 'Mga sayop sa butang sa kariton','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Magamit lang kini kon ang coupon code gipakita isip lahi nga seksyon sa checkout o cart page, ug kon ang paggamit sa coupon code gi-enable sa WooCommerce settings.','Coupon codes position' => 'Posisyon sa mga code sa kupon','Apply coupon button' => 'Buton sa paggamit sa kupon','Select style of the "apply coupon" button.' => 'Pilia ang estilo sa buton nga &quot;apply coupon&quot;.','Address line 2' => 'Linya sa adres 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Kini nga setting gipaambit tali sa mga seksyon sa Checkout ug Local pickup. Sa seksyon sa Local pickup, kini usab ang modesisyon kung ang Ship/Pickup selector makita sulod sa seksyon sa pamaagi sa pagpadala (sa wala pa ang adres) o isip usa ka lahi nga seksyon (human).','Customer accounts' => 'Mga account sa kustomer','Guest checkout' => 'Pag-checkout sa bisita','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Mga opsyon sa pag-checkout sa bisita, pag-login, ug paghimo og account gikan sa panid sa mga setting sa WooCommerce Accounts. Gidumala kini dinhi para sa imong kasayon, busa magamit nimo ang lainlaing mga kantidad matag profile sa setting.','Allow customers to checkout without an account' => 'Tugoti ang mga kustomer nga mag-checkout nga walay account','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Girekomendar</strong> aron ang mga kustomer dili hangyoon sa paghimo og account o pag-log in atol sa checkout, nga makapaubos sa mga conversion rate.','When disabled, customers must log in or create an account to complete the purchase.' => 'Kung naka-disable, ang mga kustomer kinahanglan nga mag-log in o maghimo og account aron makompleto ang pagpalit.','Login at checkout' => 'Pag-login sa checkout','Enable log-in during checkout' => 'I-enable ang pag-log in atol sa checkout','Show a link for returning customers to log in from the checkout page.' => 'Ipakita ang link para sa mga mibalik nga kustomer aron mag-log in gikan sa panid sa checkout.','Account creation' => 'Paghimo og account','Allow customers to create an account during checkout' => 'Tugoti ang mga kustomer sa paghimo og account atol sa checkout','Customers can create an account before placing their order.' => 'Mahimo maghimo og account ang mga kustomer sa dili pa mag-order.','Allow customers to create an account from the My account page' => 'Tugoti ang mga kustomer sa paghimo og account gikan sa panid sa Akong account','Customers can register a new account from the My account page.' => 'Mahimo magparehistro ang mga kustomer og bag-ong account gikan sa panid sa Akong account.','Username' => 'Ngalan sa Gumagamit','Generate from customer\'s name' => 'Paghimo gikan sa ngalan sa kustomer','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Girekomendar</strong> aron ang mga kustomer dili hangyoon sa pagpili og username atol sa checkout, nga makapaubos sa mga conversion rate.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Ang username gihimo gikan sa ngalan sa kustomer, o gikan sa email address kung ang ngalan dili magamit.','Password' => 'Pasword','Send password setup link' => 'Ipadala ang link sa pag-setup sa password','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Girekomendar</strong> aron ang mga kustomer dili hangyoon sa pagbutang og password atol sa checkout, nga makapaubos sa mga conversion rates.','Customers receive an email to create their password securely.' => 'Ang mga kustomer makadawat og email aron luwas nga makahimo sa ilang password.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Tugoti ang mga rehistradong kustomer nga makompleto ang checkout nga dili na kinahanglan mag-log in ug i-associate ang order sa ilang kasamtangang account kung motakdo ang mga detalye sa pagkontak.','Existing account message' => 'Mensahe sa kasamtangang account','Let customers create an account after placing their order, from the thank you page.' => 'Tugoti ang mga kustomer sa paghimo og account human sa ilang order, gikan sa panid sa pagpasalamat.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Anaa ang mga opsyon niining seksyon kon ang guest checkout ug account matching gi-enable. I-enable ang duha ka feature sa ibabaw aron ma-configure ang nalangan nga paghimo og account.','Enable delayed account creation' => 'I-enable ang nalangan nga paghimo og account','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'I-enable ang nalangan nga paghimo og account kon ang guest checkout ug account matching parehong naka-enable.','Section position' => 'Posisyon sa seksyon','Before customer details section' => 'Sa dili pa ang seksyon sa mga detalye sa kustomer','After customer details section' => 'Human sa seksyon sa mga detalye sa kustomer','Account creation benefits' => 'Mga benepisyo sa paghimo og account','Leaving the field empty will display the default text.' => 'Ang pagbiya sa field nga walay sulod magpakita sa default nga teksto.','Inline buttons' => 'Mga butones nga inline','Required fields' => 'Gikinahanglan nga mga field','Enable gift message fields at checkout' => 'I-enable ang mga field sa mensahe sa regalo sa checkout','Expanded gift message' => 'Gipalapdan nga mensahe sa regalo','Display gift message field always expanded' => 'Kanunay nga gipalapdan ang field sa mensahe sa regalo','Gift message in order details' => 'Mensahe sa regalo sa mga detalye sa order','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Walay magamit nga mga integrasyon sa pagkakaron niining seksyon. Ang mga opsyon nga may kalabotan sa matag plugin ug tema makita lang dinhi kung ang maong plugin o tema gi-activate.','Phone fields' => 'Mga natad sa telepono','Field visibility' => 'Pagkakita sa uma','Field position' => 'Posisyon sa uma','Phone country code & validation' => 'Kodigo sa nasud sa telepono ug pag-validate','Country' => 'Nasod','Enable country on phone fields' => 'I-enable ang nasud sa mga field sa telepono','Filter countries for shipping or billing' => 'Salain ang mga nasud para sa pagpadala o pagsingil','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Limitahi ang pagpili sa nasud sa matag field sa telepono ngadto sa mga nasud nga gitugotan alang sa pagpadala o pagsingil sa imong tindahan.','Validation' => 'Pag-validate','Enable simple validation based on country rules' => 'I-enable ang simpleng pag-validate base sa mga lagda sa nasud','Checks that the phone number is valid for the selected country, including country code and length.' => 'Gisusi kung ang numero sa telepono balido para sa pinili nga nasud, lakip ang country code ug gitas-on.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Mas estrikto nga pagsusi nga ang numero balido nga mobile, fixed line, o uban pang gidawat nga tipo para sa pinili nga nasud. Mahimong isalikway ang pipila ka balido nga mga numero.','Validation types' => 'Mga klase sa pag-validate','Placeholders' => 'Mga Placeholder','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Walay mga license key nga dumalahon sa pagkakaron. Ang mga license key makita dinhi kung ang usa ka lisensyado nga Fluid Checkout plugin o add-on aktibo.','Default delivery type' => 'Default nga klase sa pagpadala','Choose which delivery type will be selected by default.' => 'Pilia kung unsang klase sa pagpadala ang pilion pinaagi sa default.','Shipping zone fields' => 'Mga natad sa sona sa pagpadala','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Pilia kung unsang mga field ang ipakita para sa mga filter field sa local pickup shipping zone. Pasagdi nga blangko aron ipakita ang tanang available nga mga opsyon.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Kini nga mga field ipakita isip filter para sa mga pamaagi sa pagpadala sa lokal nga pagkuha. Ang ubang mga field mahimong makita gihapon sa checkout kung wala kini mapili dinhi, kung ang mga compatible nga plugin nanginahanglan nga kini molihok sa husto.','Order shipping address' => 'Address sa pagpadala sa order','Order pay page optimization' => 'Pag-optimize sa panid sa pagbayad sa order','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Hatagi ang mga wala mabayri nga order og parehas nga klaro ug naka-focus sa conversion layout sama sa checkout.','Optimize the layout of the order pay page for orders pending payment.' => 'I-optimize ang layout sa panid sa pagbayad sa order para sa mga order nga pending payment.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Ipares ang kasinatian sa pagbayad sa order sa imong checkout para sa makanunayon nga panaw sa pagpalit.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Pagdugang og mga simbolo sa pagsalig ug mga badge diin ang mga mamalitay nanginahanglan og pasalig sa dili pa mobayad.','Thank you page optimization' => 'Salamat sa pag-optimize sa panid','Make the thank you page and order details clearer for customers after they buy.' => 'Himoa nga mas klaro ang panid sa pasalamat ug mga detalye sa order para sa mga kustomer human sila mopalit.','Optimize the thank you page and account order details with a clearer layout.' => 'I-optimize ang panid sa pagpasalamat ug mga detalye sa order sa account nga adunay mas klaro nga layout.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Ipakita ang progreso sa status sa order, mga aksyon, mga download, ug mga nota kung asa kini angay.','Customize order details sections on email notifications.' => 'I-customize ang mga seksyon sa mga detalye sa order sa mga notipikasyon sa email.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Pagdugang og mga simbolo sa pagsalig ug mga badge diin ang mga mamalitay nanginahanglan og kasiguroan human sa pagpalit.','Email notifications' => 'Mga notipikasyon sa email','Enable thank you page and order details optimizations to see more options' => 'I-enable ang panid sa pagpasalamat ug mga pag-optimize sa mga detalye sa order aron makakita og dugang mga kapilian','Use wide layout on thank you page' => 'Gamita ang lapad nga layout sa panid sa pagpasalamat','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Kini nga mga opsyon makaapekto sa panid sa pagpasalamat, pagtan-aw sa mga detalye sa order sa mga panid sa account ug sa mga notipikasyon sa email.','Save settings' => 'I-save ang mga setting','Docs' => 'Mga Dokumento','Cart' => 'Kariton','Thank you' => 'Salamat','Address autocomplete' => 'Awtomatikong kompletohon ang adres','Trust badges' => 'Mga badge sa pagsalig','You do not have permission to save these settings.' => 'Wala kay permiso sa pag-save niining mga setting.','Invalid save request.' => 'Dili balido ang hangyo sa pagtipig.','Your settings have been saved.' => 'Na-save na ang imong mga setting.','Saving...' => 'Nagtipig...','Settings could not be saved. Please try again.' => 'Dili ma-save ang mga setting. Palihug sulayi pag-usab.','Dismiss notice' => 'Pahibalo sa pagsalikway','Open settings menu' => 'Ablihi ang menu sa mga setting','Close settings menu' => 'Isira ang menu sa mga setting','Preview' => 'Pagtan-aw daan','Expand preview' => 'Palapdi ang preview','Collapse preview' => 'I-collapse ang preview','Show header and footer' => 'Ipakita ang header ug footer','Hide header and footer' => 'Itago ang header ug footer','Page preview' => 'Paunang tan-aw sa panid','Preview viewport' => 'I-preview ang viewport','Tablet' => 'Tableta','Desktop' => 'Desktop','Preview width' => 'Gilapdon sa preview','Decrease width' => 'Pakunhuran ang gilapdon','Preview width in pixels' => 'Gilapdon sa preview sa mga pixel','Increase width' => 'Dugangi ang gilapdon','Preview as' => 'I-preview isip','Guest' => 'Bisita','Logged in' => 'Naka-login na','Preview page' => 'Panid sa pag-preview','Expand preview for a closer look' => 'Palapdi ang preview para sa mas duol nga pagtan-aw','Available with %s.' => 'Magamit uban sa %s.','Turn them on' => 'I-on sila','Optimizations for this page are turned off. %s to preview the page.' => 'Ang mga pag-optimize para ani nga panid gipalong. %s aron makita daan ang panid.','%s preview' => '%s nga preview','Isolated session · nothing is saved' => 'Nahimulag nga sesyon · walay na-save','Usage tracking' => 'Pagsubay sa paggamit','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Pagpadala og mga report sa palibot sa site nga dili sensitibo aron matabangan ang Fluid Checkout nga mapaayo ang pagkaangay. Ang mga report dili ipadala hangtod nga ma-enable sa mga opsyon sa ubos.','Send usage tracking reports to Fluid Checkout' => 'Ipadala ang mga report sa pagsubay sa paggamit ngadto sa Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Kini nga mga report makatabang kanamo sa pagpalambo sa compatibility ug suporta para sa imong site ug ipadala kada semana kung gi-enable.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Walay kustomer, admin user, o bisan unsang uban pang sensitibo nga datos nga gilakip sa mga report.','Basic environment info' => 'Pangunang impormasyon sa palibot','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Ang datos sa listahan sa WordPress, PHP, WooCommerce, tema, ug plugin. Kanunay nga gilakip kung ang pagreport gi-enable. Makatabang kini kanamo nga masabtan ang palibot nga gigamit sa imong site.','Plugin settings' => 'Mga setting sa plugin','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Magpadala og mga setting sa Fluid Checkout plugin aron makatabang sa mga hangyo sa suporta ug motabang kanamo nga masabtan kung giunsa nimo paggamit ang among mga plugin.','Coming soon' => 'Moabot na','Sales metrics' => 'Mga sukdanan sa pagbaligya','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Ang binulan nga ihap sa order ug kinatibuk-ang halin sulod sa usa ka tuig sa wala pa i-install ang Fluid Checkout hangtod karon. Makatabang kini kanamo nga masabtan kung nakaganansya ka ba og dugang gamit ang among mga plugin nga na-install. Walay datos sa kustomer o tiggamit nga ipadala.','Utilities' => 'Mga Utility','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Gamita ang mga dropdown component <code>TomSelect</code> imbes nga <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'Ang TomSelect usa ka mas simple nga dropdown selection component nga dili kaayo daling masayop kon itandi sa Select2, samtang nagtanyag sa parehas nga gamit.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Gitakda ang gidak-on sa font sulod sa mga form field ngadto sa 16px sa mga panid nga gi-optimize niini nga plugin aron malikayan ang awtomatikong pag-zoom in kung makig-interact sa mga form field sa gagmay nga mga device.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Ang Safari ug uban pang mga browser mahimong awtomatikong mag-zoom in sa mga mobile device aron mas sayon basahon ang teksto kung ang gidak-on sa font mas gamay sa 16px.','Enable script processing tracking on the browser console.' => 'I-enable ang script processing tracking sa browser console.','Unminified assets' => 'Wala giminusan nga mga kabtangan','Google Maps scripts' => 'Mga script sa Google Maps','Do not remove duplicate Google Maps scripts' => 'Ayaw kuhaa ang doble nga mga script sa Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Kon ma-enable, ang duplicate nga Google Maps scripts DILI matangtang nga mahimong hinungdan sa mga sayop ug mga problema sa performance. Gamita lang kini nga opsyon kon mag-troubleshoot.','Widget areas' => 'Mga lugar sa widget','Last step on mobile' => 'Katapusang lakang sa mobile','Display widgets only at last step on mobile' => 'Ipakita lang ang mga widget sa katapusang lakang sa mobile','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Ipakita lang ang mga widget sa checkout trust badge kon makita ang katapusang lakang sa checkout sa mga mobile device','Standard' => 'Sumbanan','VAT number field' => 'Kahon sa numero sa VAT','Add a VAT number field to the billing form.' => 'Idugang ang field sa VAT number sa billing form.','Field label' => 'Label sa uma','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Ibutang ang label sa field sa VAT number (pananglitan, VAT number). Sa mga website nga adunay daghang pinulongan, mas maayo nga biyaan kining field nga walay sulod ug hubaron ang orihinal nga string.','VAT Number' => 'Numero sa VAT','EU-VAT' => 'EU-VAT','Enable the VAT number field to see more options' => 'I-enable ang field sa VAT number aron makakita og dugang mga opsyon','VAT validation' => 'Pag-validate sa VAT','Validate VAT number field for EU-VAT during checkout' => 'I-validate ang VAT number field para sa EU-VAT atol sa checkout','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Gisusi kung ang gihatag nga VAT Number usa ka balido nga VAT number nga narehistro sa European VIES Database (VAT Information Exchange System).','Shop VAT number' => 'Numero sa VAT sa tindahan','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Ang VAT number sa tindahan nga gigamit sa paghangyo og EU-VAT validation, ug kini giimprinta sa mga invoice.<br> <strong>Among girekomendar nga idugang ang imong Shop VAT number</strong> kay kon dili, ang resulta sa konsultasyon sa VIES mahimong dili balido para sa katuyoan sa accounting.<br> Ie.: <code>ATU99999999</code> o <code>EE999999999</code> .','Reverse charge' => 'Baliktad nga bayad','Apply reverse charge mechanism' => 'I-apply ang mekanismo sa reverse charge','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Ibutang ang tax rate sa zero ug ipakita ang &quot;Reverse charge&quot; sa mga invoice kung balido ang VAT number sa kustomer. Mahimong kinahanglan ang lahi nga teksto nga &quot;Reverse charge&quot; depende sa nasud sa tindahan.','Same country' => 'Parehas nga nasud','Apply reverse charge mechanism for transactions in the shop country:' => 'Gamita ang mekanismo sa reverse charge para sa mga transaksyon sa nasud sa tindahan:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Nagpahimo sa pag-apply sa reverse charge mechanism para sa mga transaksyon tali sa mga kompanya sa parehas nga nasud sama sa tindahan.','Reverse charge exceptions' => 'Mga eksepsiyon sa reverse charge','Select additional countries to skip applying the reverse charge mechanism.' => 'Pagpili og dugang nga mga nasud aron laktawan ang pag-apply sa reverse charge mechanism.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Maningil og buhis ang mga order gikan niining mga nasura bisan pa kon gihatag ang balido nga VAT number.','Reverse charge label on invoices' => 'Baliha nga label sa bayad sa mga invoice','Set the label of "reverse charge" on the checkout page and order details.' => 'Ibutang ang label nga &quot;reverse charge&quot; sa checkout page ug ang mga detalye sa order.','Reverse charge text on invoices' => 'Teksto sa baliktad nga singil sa mga invoice','Set the label of "reverse charge" text on invoices.' => 'Ibutang ang label nga &quot;reverse charge&quot; nga teksto sa mga invoice.','Tax to be paid on reverse charge basis' => 'Ang buhis bayran base sa reverse charge','Company name' => 'Ngalan sa kompanya','Autocomplete company name from VAT number' => 'Awtomatikong kompletoha ang ngalan sa kompanya gikan sa numero sa VAT','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Isulod ang ngalan sa kompanya sa pagbayad base sa balido nga numero sa VAT nga gihatag sa kustomer.','Company name editing' => 'Pag-edit sa ngalan sa kompanya','Allow editing of auto-filled company name' => 'Tugoti ang pag-edit sa awtomatikong gipuno nga ngalan sa kompanya','When enabled, customers can change the company name associated with the provided VAT number.' => 'Kon ma-enable, mahimong usbon sa mga kustomer ang ngalan sa kompanya nga nalangkit sa gihatag nga VAT number.','EU-VAT for digital goods' => 'EU-VAT para sa mga digital nga produkto','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Sugod Enero 1, 2015, gihimo ang mga pagbag-o sa mga regulasyon sa VAT sa EU bahin sa mga digital nga produkto, nga nakaapekto lamang sa mga transaksyon sa B2C. Ang VAT sa mga digital nga produkto kinahanglan nga kalkulado base sa lokasyon sa kustomer, ug kinahanglan nga kolektahon ang ebidensya niini (IP address ug billing address).','Tax classes for digital goods' => 'Mga klase sa buhis para sa mga digital nga produkto','Select some tax classes' => 'Pagpili og pipila ka klase sa buhis','Location evidence' => 'Ebidensya sa lokasyon','Collect customer\'s location evidence' => 'Kolektaha ang ebidensya sa lokasyon sa kustomer','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'I-save ang IP address ug i-validate kini batok sa billing address sa kustomer. Kinahanglan kumpirmahon sa kustomer ang ilang billing address pinaagi sa pag-check sa checkbox sa checkout page kung ang nasud gikan sa ilang billing address ug IP dili magkatugma.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Kini nga opsyon gidumala sa Fluid Checkout. <a href="%s">Usba kini sa mga setting sa Customer accounts</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Kini nga opsyon gidumala sa Fluid Checkout. Usba kini ubos sa Fluid Checkout &gt; Mga account sa kustomer.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Kini nga opsyon gidumala sa Fluid Checkout. Ang destinasyon sa pagpadala kanunay nga gibutang sa &quot;Default to customer shipping address&quot; kung gi-activate ang Fluid Checkout. Ang mga kustomer makahatag gihapon og lain-laing mga shipping ug billing address atol sa checkout.<br><br> Adunay opsyon para sa pag-set sa default billing address nga parehas sa shipping address sa <a href="%s">Fluid Checkout settings</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Kini nga opsyon gidumala sa Fluid Checkout. Ang destinasyon sa pagpadala kanunay nga gibutang sa &quot;Default to customer shipping address&quot; kung gi-activate ang Fluid Checkout. Ang mga kustomer makahatag gihapon og lain-laing mga shipping ug billing address atol sa checkout.<br><br> Ang opsyon para sa pag-set sa default billing address nga parehas sa shipping address makita sa WooCommerce &gt; Settings &gt; Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Kini nga mga setting gibalhin na sa WP Admin &gt; Fluid Checkout &gt; Settings.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Kini nga tab sa WooCommerce Settings wala na gigamit ug tangtangon na sa Fluid Checkout 6.0.','Go to settings page' => 'Adto sa panid sa mga setting','Hide this tab permanently' => 'Itago kini nga tab permanente','Site report preview' => 'Preview sa report sa site','This is the data that would be included in the next site environment report based on your current settings.' => 'Kini ang datos nga ilakip sa sunod nga report sa palibot sa site base sa imong kasamtangang mga setting.','Loading report preview...' => 'Nagkarga sa preview sa report...','Could not load the site report preview. Try again.' => 'Dili ma-load ang preview sa report sa site. Sulayi pag-usab.','Could not send the site report. Try again.' => 'Dili mapadala ang report sa site. Sulayi pag-usab.','Site report sent successfully.' => 'Malampusong napadala ang report sa site.','Enable and send now' => 'I-enable ug ipadala karon','Close' => 'Sira','A site report request is already in progress. Try again in a moment.' => 'Usa ka hangyo sa site report ang nagpadayon na. Sulayi pag-usab inig human.','Site environment reporting is disabled.' => 'Ang pagreport sa palibot sa site wala gipagana.','No site report data is available to send.' => 'Walay datos sa report sa site nga magamit aron ipadala.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Kini nga site domain dili makapadala og mga report sa palibot (wala gilakip ang lokal o development domain).','A site report was sent recently. Try again later.' => 'Usa ka report sa site ang gipadala bag-o lang. Sulayi pag-usab sa ulahi.','The site report could not be sent. Try again later.' => 'Dili mapadala ang report sa site. Sulayi pag-usab sa ulahi.','Site environment reporting is not available.' => 'Dili magamit ang pagreport sa palibot sa site.','No site report data is available for the selected settings.' => 'Walay datos sa report sa site nga magamit para sa mga pinili nga setting.','You are not allowed to manage site reports.' => 'Dili ka gitugotan sa pagdumala sa mga report sa site.','PRO feature' => 'PRO nga bahin','Other plugins' => 'Ubang mga plugin','Get only this add-on &mdash; %s' => 'Kuhaa lang kini nga add-on — %s','Install add-on' => 'I-install ang add-on','Upgrade to PRO &mdash; %s' => 'I-upgrade ngadto sa PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Kuhaa ang %2$s</a> aron maablihan kini nga mga kapilian.','Add-on' => 'Dugang','View documentation' => 'Tan-awa ang dokumentasyon','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Ang mga hangyo nanginahanglan og naka-login nga WordPress user. Ayaw gamita ang user_id aron magamit ang datos sa kasamtangang user, o ipasa ang user_id aron i-target ang laing account kung ang nanawag maka-edit sa maong user (edit_user capability). Ang wala ma-authenticate nga mga hangyo mobalik sa fc_api_forbidden. Ang dili balido nga user_id mobalik sa fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 nga adunay { &quot;data&quot;: { ... } } kung ang handler mobalik og payload.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 nga adunay { &quot;success&quot;: true } kung walay payload (pananglitan DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Ang mga kapakyasan mobalik sa WordPress REST error nga JSON gikan sa WP_Error (code, message, data.status). Ang mga wire code mogamit sa fc_api_* prefix.','Forbidden access.' => 'Gidili nga pagsulod.','Target user was not found.' => 'Wala nakit-an ang target nga tiggamit.','This feature is not available.' => 'Kini nga bahin dili magamit.','A required address field is missing.' => 'Nawala ang gikinahanglan nga address field.','Postcode or ZIP is invalid.' => 'Dili balido ang postcode o ZIP.','Phone number is invalid.' => 'Dili balido ang numero sa telepono.','State or county is invalid.' => 'Dili balido ang estado o lalawigan.','Country is invalid or has no address fields.' => 'Dili balido ang nasud o walay mga field sa adres.','The request could not be processed.' => 'Dili maproseso ang hangyo.','Back to previous step' => 'Balik sa miaging lakang','Skip to settings' => 'Laktawan ang mga setting','Start over and return to the first guided setup step' => 'Sugdi pag-usab ug balik sa unang giya nga lakang sa pag-setup','Start over' => 'Sugdi pag-usab','Please complete all sub-steps before continuing.' => 'Palihug kompletoha ang tanang sub-lakang sa dili pa magpadayon.','Expand' => 'Palapdi','Collapse' => 'Gub-on','Skip' => 'Laktawan','Mark as complete' => 'Markahi nga kompleto','Mark as incomplete' => 'Markahi nga dili kompleto','View full-size image: %s' => 'Tan-awa ang tibuok gidak-on nga hulagway: %s','Full-size setup guide image' => 'Imahe sa giya sa pag-setup nga bug-os nga gidak-on','Close image' => 'Sirad-i ang hulagway','Fluid Checkout Guided Setup' => 'Pag-setup nga Giya sa Fluid Checkout','Welcome' => 'Maayong pag-abot','Explore your checkout' => 'Susiha ang imong checkout','All set' => 'Andam na ang tanan','You do not have permission to access this page.' => 'Wala kay permiso nga maka-access niining panid.','Go to step %1$d: %2$s' => 'Adto sa lakang %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Kining giya nga pag-setup makatabang nimo nga masinati ang Fluid Checkout. Ang mga lakang sa ubos mga placeholder lang sa pagkakaron.','Continue to the next step when you are ready.' => 'Padayon sa sunod nga lakang kon andam ka na.','Open your store checkout to see Fluid Checkout in action.' => 'Ablihi ang imong checkout sa tindahan aron makita ang Fluid Checkout nga naglihok.','View checkout page' => 'Tan-awa ang panid sa pag-checkout','You can return to Fluid Checkout settings to continue configuring your store.' => 'Mahimo kang mobalik sa mga setting sa Fluid Checkout aron ipadayon ang pag-configure sa imong tindahan.','Review checkout and cart settings' => 'Ribyuha ang mga setting sa checkout ug cart','Explore add-ons from the dashboard' => 'Susiha ang mga add-on gikan sa dashboard','Finish & go to settings' => 'Tapusa ug adto sa mga setting','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'I-update ang opsyon sa billing phone field visibility gikan sa legacy value aron mohaom sa mga kombensiyon sa WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'I-update ang opsyon sa shipping phone field visibility gikan sa legacy value aron mohaom sa mga kombensiyon sa WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopyaha ang setting sa kolor sa background sa summary sa order ngadto sa bag-ong opsyon sa kolor sa background sa ikaduhang kolum sa Split design.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Ang gipauswag nga bahin sa pagpili og mga natad kanunay nga dili magamit kung gamiton ang Biteship plugin.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Ang posisyon sa place order kanunay nga gibutang sa &quot;Ubos sa summary sa order&quot; kung mogamit sa German Market. Kinahanglan nga ipakita sa plugin ang buton sa place order ug ang mga legal nga checkbox sa ubos sa summary sa order.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Ang posisyon sa place order kanunay nga gibutang sa &quot;Ubos sa summary sa order&quot; kung gamiton ang Germanized para sa WooCommerce. Kinahanglan nga ipakita sa plugin ang buton sa place order ug ang mga legal nga checkbox sa ubos sa summary sa order.','Edit pickup locations' => 'I-edit ang mga lokasyon sa pagkuha','Use local pickup label from WooCommerce settings' => 'Gamita ang lokal nga label sa pagkuha gikan sa mga setting sa WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Kon gi-enable, ang label sa opsyon sa pagkuha sa checkout motakdo sa titulo gikan sa mga setting sa lokasyon sa pagkuha sa WooCommerce. Kon gi-disable, ang label mogamit sa mahubad nga teksto nga &quot;Local pickup&quot; gikan sa Fluid Checkout.','Button label for applying coupon codesApply' => 'Pag-apply','Checkout step titleContact' => 'Kontaka','Checkout step titleShipping' => 'Pagpadala','Checkout step titleBilling' => 'Pagsingil','Checkout step titlePayment' => 'Bayad','Checkout substep change link labelChange' => 'Pagbag-o','Checkout substep save link labelSave changes' => 'I-save ang mga pagbag-o','Substep review textNone.' => 'Wala.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Walay hulagway nga gipili.','Settings sectionCart' => 'Cart','Settings sectionOrder pay' => 'Bayad sa order','Settings sectionThank you' => 'Salamat','Settings section titleIntegrations' => 'Mga panagsama','Settings section titleLicense keys' => 'Mga yawe sa lisensya','Captcha positionBefore place order section' => 'Sa wala pa ang place order section','Captcha positionBefore place order button' => 'Sa wala pa ibutang ang order nga buton','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Duol','Log in link label at checkout contact stepLog in' => 'Log in','Log in separator label at for when guest checkout is disabledOr continue below' => 'O magpadayon sa ubos','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'O magpadayon isip bisita','Clear image selection on admin pages.Remove image' => 'Kuhaa ang hulagway','shipping packagesShipping %d' => 'Pagpadala %d','shipping packagesShipping' => 'Pagpadala','Used as fallback for "Proceed to next step" button labelnext step' => 'sunod nga lakang','Substep review checkbox valueYes' => 'Oo','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Juan','Dummy customer last name in the admin previewDoe' => 'Usa','Dummy customer company in the admin previewExample Company' => 'Ehemplo nga Kompanya','Dummy customer street address in the admin preview123 Main Street' => '123 Pangunang Dalan','Dummy customer city in the admin previewAnytown' => 'Bisan unsang lungsod','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Palihug ibilin ang pakete sa atubangan nga pultahan.','Dummy product name in the admin previewBeanie' => 'Beanie','Dummy product name in the admin previewCap' => 'Taklob','Dummy product name in the admin previewT-Shirt' => 'T-Shirt','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Nadawat namo ang imong order ug padad-an ka namo og update kung ipadala na kini.','Dummy download in the admin previewUser guide' => 'Giya sa tiggamit','Google Places API versionsPlaces API (New)' => 'API sa mga Dapit (Bag-o)','Google Places API versionsPlaces API (Legacy)' => 'Places API (Kabilin)','Brasil API versionsVersion 1' => 'Bersyon 1','Brasil API versionsVersion 2' => 'Bersyon 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
